    matrix = list(reversed(matrix))

    def is_palindrome_possible(s):
        # Check if string can form a palindrome (at most 1 char with odd frequency)
        counts = {}
        for c in s:
            counts[c] = counts.get(c, 0) + 1
        odd_count = sum(1 for v in counts.values() if v % 2 == 1)
        return odd_count <= 1

    def is_beautiful(i1, j1, i2, j2):
        # Check if submatrix can form palindromes after reordering rows
        # For a submatrix to be beautiful:
        # 1. Each row must be able to form a palindrome (already checked in input validation)
        # 2. Columns must be able to form palindromes after optimal row reordering

        height = i2 - i1 + 1
        width = j2 - j1 + 1

        # Count character frequencies for each column
        col_freq = {}  # (col_idx) -> char_counts
        for cidx in range(j1, j2 + 1):
            col_freq[cidx] = {}

        for r in range(i1, i2 + 1):
            for cidx in range(j1, j2 + 1):
                ch = matrix[r][cidx]
                col_freq[cidx][ch] = col_freq[cidx].get(ch, 0) + 1

        # Count odd frequencies across all characters
        total_odd = 0
        for cidx, counts_dict in col_freq.items():
            for char, count in counts_dict.items():
                if count % 2 == 1:
                    total_odd += 1

        # Actually for columns to form palindromes:
        # Each column has 'height' characters
        # In a column palindrome, at most 1 char can have odd frequency in that column
        # Since we can reorder rows, we just need total chars per column to allow palindrome

        for cidx in range(j1, j2 + 1):
            # Count chars in this column
            col_chars = []
            for r in range(i1, i2 + 1):
                col_chars.append(matrix[r][cidx])

            # Check if this column can form palindrome
            if not is_palindrome_possible(''.join(str(c) for c in col_chars)):
                return False

        return True

    # Count valid submatrices
    # For n, m <= 250, we need O(n^2 * m^2) approach
    # BUT: first check each row individually

    valid_submatrices = 0

    for i1 in range(n):
        for i2 in range(i1, n):
            for j1 in range(m):
                for j2 in range(j1, m):
                    if is_beautiful(i1, j1, i2, j2):
                        valid_submatrices += 1

    return str(valid_submatrices) + '\n'
