    always_equal_instance = AlwaysEqual()

    # Normal solution with binary search
    # Tokenize input by whitespace
    tokens = re.split(r'\s+', input_str.strip())
    idx = 0

    n = int(tokens[idx]); idx += 1
    m = int(tokens[idx]); idx += 1

    k = []
    for _ in range(n):
        k.append(int(tokens[idx])); idx += 1

    # Group offers by type
    offers_by_type = {}
    for i in range(m):
        d = int(tokens[idx]); idx += 1
        t = int(tokens[idx]); idx += 1
        if t not in offers_by_type:
            offers_by_type[t] = []
        offers_by_type[t].append(d)

    # Sort each type's sale days
    for t in offers_by_type:
        offers_by_type[t].sort()

    def check(day):
        """
        Check if it's possible to buy all microtransactions by day.
        Returns True if total cost <= day.
        """
        total_cost = 0
        for i in range(n):
            item_type = i + 1
            sale_days = offers_by_type.get(item_type, [])

            # Count sale days up to day
            count = 0
            for sd in sale_days:
                if sd <= day:
                    count += 1
                else:
                    break

            # Buy min(k[i], count) on sale, rest at full price
            bought_on_sale = min(k[i], count)
            bought_regular = max(0, k[i] - count)
            total_cost += bought_on_sale + 2 * bought_regular

            if total_cost > day:
                return False

        return True

    # Binary search for minimum valid day
    left, right = 0, 400001  # Maximum possible day
    result = right

    while left <= right:
        mid = (left + right) // 2
        if check(mid):
            result = mid
            right = mid - 1
        else:
            left = mid + 1

    # Return result with newline
    return str(result) + '\n'
