    if cp1 == 0 and on_segment(p1, q1, q2): return True
    if cp2 == 0 and on_segment(p2, q1, q2): return True
    if cp3 == 0 and on_segment(q1, p1, p2): return True
    if cp4 == 0 and on_segment(q2, p1, p2): return True

    return False

def is_diagonal_valid(i, j, n, points):
    """Check if diagonal (i,j) is a valid internal diagonal"""
    # Must not be an existing polygon edge
    if abs(i - j) == 1 or (i == 0 and j == n - 1):
