                        if grid[row][left] != '1' or grid[row][right] != '1':
                            valid = False
                            break
                    if not valid:
                        continue

                    # Check no foreign 1s touch the border (including diagonally)
                    checked = set()
                    for row in range(top, bottom + 1):
                        for col in range(left, right + 1):
                            if grid[row][col] == '1':
                                for dr in [-1, 0, 1]:
                                    for dc in [-1, 0, 1]:
                                        if dr == 0 and dc == 0:
                                            continue
                                        nr, nc = row + dr, col + dc
                                        if 0 <= nr < n and 0 <= nc < m:
                                            key = (nr, nc)
                                            if (nr, nc) == (row, col):
                                                continue
                                            if key not in checked and grid[nr][nc] == '1':
                                                valid = False
                                                break
                                    if not valid:
                                        break
                            if not valid:
                                break
                        if not valid:
                            break
                    if not valid:
                        continue

                    # Mark as checked
                    for row in range(top, bottom + 1):
                        for col in range(left, right + 1):
                            if grid[row][col] == '1':
                                for dr in [-1, 0, 1]:
                                    for dc in [-1, 0, 1]:
                                        if dr == 0 and dc == 0:
                                            continue
                                        nr, nc = row + dr, col + dc
                                        checked.add((nr, nc))

                    # If size >= 2, we need at least one interior 1
                    if size > 1 and size > 2:
                        has_interior_1 = False
                        for row in range(top + 1, bottom):
                            for col in range(left + 1, right):
                                if grid[row][col] == '1':
                                    has_interior_1 = True
                                    break
                            if has_interior_1:
                                break
                        if not has_interior_1:
                            continue

                    # Also need all interior to be 0 for it to be a valid frame
                    interior_ok = True
                    for row in range(top + 1, bottom):
                        for col in range(left + 1, right):
                            if grid[row][col] == '1':
                                interior_ok = False
                                break
                        if not interior_ok:
                            break
                    if not interior_ok:
                        continue

                    count += 1

        # Diagonal squares - diamonds with Manhattan distance k from center
        for cr in range(n):
            for cc in range(m):
                for k in range(1, min(n, m) + 1):
                    # Build diamond border and check validity
                    border = []
                    interior = []

                    for i in range(n):
                        for j in range(m):
                            dist = abs(i - cr) + abs(j - cc)
                            if dist == k:
                                border.append((i, j))
                            elif dist < k:
                                interior.append((i, j))

                    if not border:
                        continue

                    # All border cells must be 1
                    all_border_1 = all(grid[r][c] == '1' for r, c in border)
                    if not all_border_1:
                        continue

                    # Interior cells must be 0
                    all_interior_0 = all(grid[r][c] == '0' for r, c in interior)
                    if not all_interior_0:
                        continue

                    # Check no foreign 1s at distance k+1 (around the diamond)
                    valid = True
                    diamond_cells = set(border)
                    for r in range(n):
                        for c in range(m):
                            dist = abs(r - cr) + abs(c - cc)
                            if dist == k + 1 and (r, c) not in diamond_cells:
                                if grid[r][c] == '1':
                                    valid = False
                                    break
                        if not valid:
                            break
                    if not valid:
                        continue

                    count += 1

        results.append(str(count))

    return '\n'.join(results)
