# Actual correct solution
def solution(input_str):
    MOD = 10**9 + 7

    parts = input_str.strip().split()
    if not parts:
        return ""

    k = int(parts[0])
    pa = int(parts[1])
    pb = int(parts[2])

    # Compute modular inverse of (pa + pb)
    inv = pow(pa + pb, MOD - 2, MOD)
    p = pa * inv % MOD  # Probability of adding 'a'
    q = pb * inv % MOD  # Probability of adding 'b'

    # dp[i][j] = expected additional 'ab' subsequences given we have i 'ab' subsequences and j 'a's
    dp = [[0] * (k + 1) for _ in range(k + 1)]

    # Fill dp table - for states where i+j < k (haven't reached k 'ab' yet)
    # Process from highest i,j down to (0,0)
    for i in range(k - 1, -1, -1):
        for j in range(k - 1, -1, -1):
            # dp[i][j+1] - if we add 'a', we have same 'ab' count, but j+1 a's
            term1 = dp[i][j + 1] * p
            # dp[i+j][j] - if we add 'b', we have i+j 'ab' subsequences
            if i + j < k:
                term2 = dp[i + j][j] * q
            else:
                term2 = 0  # If i+j >= k, we stop after this transition, so additional = 0

            dp[i][j] = (term1 + term2) % MOD

    # The answer is k (when we stop, we have at least k 'ab') + expected additional from state (0,0)
    answer = (k + dp[0][0]) % MOD
    return str(answer)
