def solution(input_str):
    """
    Simulate the frog jumping game.

    Strategy:
    - Track active frogs at their positions
    - For each frog's turn, calculate which other frogs are on the jump path
    - Eliminate frogs on the path, decrease jump distance
    - Continue until all frogs have been processed or no more eliminations occur
    """
    lines = input_str.strip().split('\n')
    if len(lines) < 1:
        return "0\n"

    n, m = map(int, lines[0].split())

    # Parse frog data (0-indexed internally)
    frog_positions = []
    frog_a = []
    frog_ids = []

    for i in range(1, len(lines)):
        if i >= n + 1:
            break
        p, a = map(int, lines[i].split())
        frog_ids.append(i)
        frog_positions.append(p - 1)  # 0-indexed
        frog_a.append(a)

    # Track which frogs are still active
    active = [True] * n

    # Simulation loop - continue until no eliminations in a full cycle
    eliminated_in_cycle = True
    cycle_count = 0
    max_cycles = n * max(frog_a) + n if frog_a else n

    while cycle_count < max_cycles and eliminated_in_cycle:
        eliminated_in_cycle = False

        for i in range(n):
            if not active[i]:
                continue

            ai = frog_a[i]
            if ai <= 0:
                continue

            current_pos = frog_positions[i]
            dest_pos = (current_pos + ai) % m

            # Find frogs knocked out on the path
            # Path: from (current_pos + 1) to dest_pos (wrapping around if needed)
            knocked = []

            for j in range(n):
                if not active[j] or j == i:
                    continue

                other_pos = frog_positions[j]

                # Check if other frog is on the jump path
                if dest_pos >= current_pos:
                    # Path doesn't wrap: current_pos < other_pos <= dest_pos
                    if current_pos < other_pos and other_pos <= dest_pos:
                        knocked.append(j)
                else:
                    # Path wraps: other_pos > current_pos AND other_pos <= dest_pos OR other_pos in [0, 1, ..., dest_pos]
                    if (other_pos > current_pos and other_pos < m) or other_pos <= dest_pos:
                        knocked.append(j)

            if knocked:
                for j in knocked:
                    active[j] = False
                frog_a[i] -= len(knocked)
                eliminated_in_cycle = True

        cycle_count += 1

    # Collect surviving frogs
    survivors = [frog_ids[i] for i in range(n) if active[i]]
    survivors.sort()

    result = str(len(survivors)) + "\n"
    result += " ".join(map(str, survivors)) + " "

    return result
